import math

def get_divisors(n):
    divs = set()
    for i in range(1, int(math.sqrt(n)) + 1):
        if n % i == 0:
            divs.add(i)
            divs.add(n // i)
    return sorted(list(divs))

def solve_search(N_max):
    results = {}

    for n in range(1, N_max + 1):
        divisors = get_divisors(n)
        tau_n = len(divisors)

        if tau_n >= 5:
            # Divisors are 1, d2, d3, d4, d5, ...
            # a = second smallest (index 1)
            # b = third smallest (index 2)
            # c = fifth smallest (index 4)

            if len(divisors) < 5:
                # Should not happen if tau_n >= 5, but safety check
                continue 

            a = divisors[1]
            b = divisors[2]
            c = divisors[4]

            # Check the condition: n = ab + ac + bc
            sum_terms = a*b + a*c + b*c

            if sum_terms == n:
                if tau_n not in results:
                    results[tau_n] = []
                results[tau_n].append(n)

    return results

N_MAX = 20000
solutions = solve_search(N_MAX)

print(f"Found solutions up to N={N_MAX}: {solutions}")
print(f"Unique tau(n) values found: {list(solutions.keys())}")
